begin
  -- Raises one reorder request when an item falls to or below its reorder point,
  -- and was previously above it, or if it was already below/at and the count changed.
  if reorder_rules.needs_reorder(:new.on_hand, :new.reorder_point)
     and not reorder_rules.needs_reorder(:old.on_hand, :old.reorder_point)
    or (:new.on_hand <= :new.reorder_point and :old.on_hand > :old.reorder_point) then
    insert into reorder_requests (sku) values (:new.sku);
  end if;
end inventory_levels_au;
